    add     bx, 2
    jmp     1b
2:  mov     ax, cs
    mov     es, ax

    /* replay the stream: {op, value} byte pairs */
    mov     si, offset stream
3:  lodsw                               /* al = op, ah = value */
    cmp     al, 1
    je      op_a2
    cmp     al, 2
    je      op_a0
    cmp     al, 3
    je      op_idle
    cmp     al, 4
    je      op_gmode
    cmp     al, 5
    je      op_gtile
    jmp     done
op_a2:
    call    wait_notfull
    mov     al, ah
    out     0xA2, al
    jmp     3b
op_a0:
    call    wait_notfull
    mov     al, ah
    out     0xA0, al
    jmp     3b
op_idle:
    call    wait_idle
    jmp     3b
op_gmode:
    mov     al, ah
    out     0x7C, al
    jmp     3b
op_gtile:
    mov     al, ah
    out     0x7E, al
    jmp     3b

done:
    call    wait_idle
    mov     dx, offset s_done
    call    puts
    mov     ah, 0x08                    /* wait for a key, no echo */
    int     0x21
    mov     ax, 0x4C00
    int     0x21

wait_notfull:                           /* status bit 1: the FIFO is FULL */
    push    ax
4:  in      al, 0xA0
    test    al, 0x02
    jnz     4b
    pop     ax
    ret
wait_idle:                              /* DRAWING (bit 3) clear and the FIFO EMPTY (bit 2) */
    push    ax
5:  in      al, 0xA0
    and     al, 0x0C
    cmp     al, 0x04
    jne     5b
    pop     ax
    ret
puts:                                   /* DX = '$'-terminated string */
